import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.CdvW4CUT.js";const o="/assets/shots/access.png",u=JSON.parse('{"title":"授权管理","description":"CertHub 授权管理的四类凭据、各面板 / 云厂商字段怎么填、EAB 凭据与群晖设备 ID 的获取方式。","frontmatter":{"title":"授权管理","description":"CertHub 授权管理的四类凭据、各面板 / 云厂商字段怎么填、EAB 凭据与群晖设备 ID 的获取方式。"},"headers":[],"relativePath":"docs/access.md","filePath":"docs/access.md","lastUpdated":null}'),s={name:"docs/access.md"};function l(n,t,i,h,c,b){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="授权管理" tabindex="-1">授权管理 <a class="header-anchor" href="#授权管理" aria-label="Permalink to &quot;授权管理&quot;">​</a></h1><p>授权是流水线访问外部系统的钥匙：DNS 解析、主机登录、面板接口、云厂商 API 全都在这里维护。<strong>流水线里只选授权，不填凭据</strong> —— 换账号时改一条授权，所有引用它的流水线一起生效。</p><p><img src="'+o+'" alt="授权管理"></p><h2 id="四类授权" tabindex="-1">四类授权 <a class="header-anchor" href="#四类授权" aria-label="Permalink to &quot;四类授权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>用途</th><th>典型类型</th></tr></thead><tbody><tr><td><strong>云厂商</strong></td><td>写 DNS-01 验证记录、上传证书到 CDN / 对象存储 / 负载均衡</td><td>阿里云、腾讯云、华为云、火山引擎、AWS、Cloudflare、七牛、京东云…</td></tr><tr><td><strong>主机</strong></td><td>SSH / FTP 登录服务器下发证书并重载服务</td><td>主机 SSH、FTP 服务器</td></tr><tr><td><strong>面板</strong></td><td>通过面板 API 部署（宝塔、1Panel、群晖、PVE、NPM、雷池…）</td><td>面板类</td></tr><tr><td><strong>证书签发</strong></td><td>保存 EAB 凭据（ACME 账户私钥由系统自动生成并回写）</td><td>EAB 凭据</td></tr></tbody></table><p>共 <strong>41 种</strong>授权类型，完整清单见 <a href="/ecosystem.html">生态集成</a>。</p><h2 id="添加与测试" tabindex="-1">添加与测试 <a class="header-anchor" href="#添加与测试" aria-label="Permalink to &quot;添加与测试&quot;">​</a></h2><ol><li><strong>授权管理 → 新建授权</strong>，选类型（下拉按分类过滤）。</li><li>填字段 → 保存。</li><li>点该行的 <strong>测试</strong>，系统会真的登录 / 调接口一次，把权限、端口、两步验证问题当场暴露出来，而不是等流水线跑到一半才报错。</li></ol><div class="tip custom-block"><p class="custom-block-title">字段留空 = 不修改</p><p>编辑授权时，密码类字段留空表示「这一项没改」，后端会还原旧值。<strong>不会</strong>把密钥写成空串 —— 所以放心点保存。</p></div><h2 id="凭据的显示规则" tabindex="-1">凭据的显示规则 <a class="header-anchor" href="#凭据的显示规则" aria-label="Permalink to &quot;凭据的显示规则&quot;">​</a></h2><p>这是本项目的<strong>铁律</strong>，和很多同类系统不一样：</p><ul><li>接口层<strong>明文返回</strong>凭据，不做 <code>******</code> 打码 —— 排障时能直接确认到底填了什么。</li><li>界面上的密码框默认显示星号，点右侧「小眼睛」立刻显示明文。</li><li>保存前统一 trim：粘贴 AK 时带的首尾空格 / 换行会导致签名失败，且极难排查。</li><li>因此<strong>数据库与备份文件本身要当机密文件对待</strong>，别随手丢到公共网盘。</li></ul><h2 id="云厂商授权" tabindex="-1">云厂商授权 <a class="header-anchor" href="#云厂商授权" aria-label="Permalink to &quot;云厂商授权&quot;">​</a></h2><h3 id="dns-能力-可做-dns-01-验证" tabindex="-1">DNS 能力（可做 DNS-01 验证） <a class="header-anchor" href="#dns-能力-可做-dns-01-验证" aria-label="Permalink to &quot;DNS 能力（可做 DNS-01 验证）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务商</th><th>需要填</th><th>权限建议</th></tr></thead><tbody><tr><td>阿里云</td><td>AccessKey ID / Secret</td><td>只给 <code>AliyunDNSFullAccess</code></td></tr><tr><td>腾讯云 / DNSPod</td><td>SecretId / SecretKey</td><td>只给 DNSPod 相关权限</td></tr><tr><td>华为云</td><td>AccessKey ID / Secret Access Key / Region</td><td>云解析只读 + 修改</td></tr><tr><td>Cloudflare</td><td>API Token / Zone ID</td><td>Token 权限：<code>Zone.DNS:Edit</code></td></tr><tr><td>GoDaddy</td><td>API Key / API Secret</td><td>生产 Key（OTE 测试 Key 无效）</td></tr><tr><td>NameSilo</td><td>API Key</td><td>账号级 Key</td></tr></tbody></table><h3 id="其它云厂商" tabindex="-1">其它云厂商 <a class="header-anchor" href="#其它云厂商" aria-label="Permalink to &quot;其它云厂商&quot;">​</a></h3><p>阿里云、腾讯云、华为云、火山引擎、AWS、七牛、天翼云、京东云、多吉云、易盾、括彩云、我爱云、白山云、又拍云、Fastly、百度智能云、TrustAsia、UCloud、金山云、雨云等授权，主要用于把证书上传到 CDN / 对象存储 / 负载均衡。</p><div class="warning custom-block"><p class="custom-block-title">用子账号，不要用主账号 AK</p><p>只授予「DNS 解析」或「CDN 证书」相关权限即可。主账号 AK 泄露等于整台云账号失守。</p></div><h2 id="主机授权" tabindex="-1">主机授权 <a class="header-anchor" href="#主机授权" aria-label="Permalink to &quot;主机授权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>主机地址 / 端口</td><td>默认 22</td></tr><tr><td>用户名</td><td>建议用有 sudo 权限的专用账号</td></tr><tr><td>认证方式</td><td>密码 / 私钥（私钥支持带 passphrase）</td></tr></tbody></table><p>部署到 Nginx / Apache / Tomcat / HAProxy / IIS 时，需要能写证书目录并执行重载命令；如果账号不是 root，记得在 sudoers 里放行 <code>nginx -s reload</code> 这类命令。</p><h2 id="面板授权" tabindex="-1">面板授权 <a class="header-anchor" href="#面板授权" aria-label="Permalink to &quot;面板授权&quot;">​</a></h2><h3 id="宝塔面板" tabindex="-1">宝塔面板 <a class="header-anchor" href="#宝塔面板" aria-label="Permalink to &quot;宝塔面板&quot;">​</a></h3><p>填 <strong>面板地址</strong>（含端口，例如 <code>https://1.2.3.4:8888</code>）与 <strong>接口密钥</strong>（面板 → 设置 → API 接口）。部署时支持多站点选择。</p><h3 id="_1panel" tabindex="-1">1Panel <a class="header-anchor" href="#_1panel" aria-label="Permalink to &quot;1Panel&quot;">​</a></h3><p>填 <strong>面板地址</strong> 与 <strong>API 密钥</strong>（面板 → 面板设置 → API 接口）。</p><h3 id="群晖-dsm" tabindex="-1">群晖 DSM <a class="header-anchor" href="#群晖-dsm" aria-label="Permalink to &quot;群晖 DSM&quot;">​</a></h3><p>群晖是字段最多的一家，因为它要处理两步验证：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>DSM 地址 / 版本</td><td>例如 <code>https://192.168.1.10:5001</code></td></tr><tr><td>账号 / 密码</td><td>建议用管理员账号</td></tr><tr><td>已开启二步验证</td><td>打开后才会出现下面几项</td></tr><tr><td>设备 ID</td><td><strong>推荐</strong>：点「获取设备 ID」按钮生成受信设备令牌，之后登录不再需要验证码</td></tr><tr><td>验证密钥（可选兜底）</td><td>Base32 密钥，部署时用 <code>pyotp</code> 现算 6 位码，适合设备 ID 过期时自动回退</td></tr><tr><td>设为默认证书 / 证书名称</td><td>决定部署后是否替换 DSM 的默认证书</td></tr><tr><td>忽略证书校验</td><td>自签证书 / IP 访问时打开</td></tr></tbody></table><p><strong>获取设备 ID 的前置条件</strong>（DSM 侧）：控制面板 → 安全性 → 勾选「允许网页浏览器的用户通过信任设备来跳过双重验证」。之后在授权里填好地址 / 账号 / 密码，输一次双重认证 APP 上的 6 位码，点「获取设备 ID」即可。</p><p>设备 ID 约 <strong>30 天</strong>过期。部署时如果带设备 ID 登录失败、且授权里配了「验证密钥」，系统会自动回退成验证码登录，并把新的 did 写回授权。</p><h3 id="其它面板" tabindex="-1">其它面板 <a class="header-anchor" href="#其它面板" aria-label="Permalink to &quot;其它面板&quot;">​</a></h3><table tabindex="0"><thead><tr><th>面板</th><th>字段</th></tr></thead><tbody><tr><td>威联通 QTS</td><td>地址、账号、密码、忽略证书校验</td></tr><tr><td>Proxmox VE</td><td>地址、API Token ID / Secret、节点名</td></tr><tr><td>Nginx Proxy Manager</td><td>地址、登录邮箱、密码</td></tr><tr><td>雷池 WAF</td><td>访问地址、ApiToken</td></tr></tbody></table><h2 id="证书签发-eab-凭据" tabindex="-1">证书签发：EAB 凭据 <a class="header-anchor" href="#证书签发-eab-凭据" aria-label="Permalink to &quot;证书签发：EAB 凭据&quot;">​</a></h2><p>EAB（External Account Binding）是部分 CA 要求的账号绑定凭据。<strong>放在授权管理里，任务里只选不填</strong> —— 因为 Google 的 EAB key 创建后 <strong>7 天失效</strong>，放任务里就得逐条流水线改，改漏一条就永远签不出来。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>所属 CA</td><td>必须和任务里选的 CA 一致（Google / ZeroSSL / FreeSSL-LiteSSL）</td></tr><tr><td>EAB Key ID</td><td>CA 控制台给的 Key ID（Google 叫 keyId，SSL.com 叫 Account Key）</td></tr><tr><td>EAB HMAC Key</td><td>base64 串，粘贴时<strong>只复制标签后面的值</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">关于 EAB 的两个坑</p><ol><li><strong>Google 的 EAB 7 天失效</strong>：过期后报 <code>Unknown external account binding (EAB) key</code>，去控制台重新取一份，更新这条授权即可。</li><li><strong>FreeSSL / LiteSSL 的 EAB 只能用一次</strong>：注册成功后再注册会返回 <code>External account binding has already been used</code>。系统会在首次注册成功后把<strong>账户私钥 + 账户 URL 同时写回任务和 EAB 授权</strong>，其它流水线复用同一份 EAB 时直接复用账户，不会重复注册。</li></ol></div><p>粘贴整段文本（含「Key ID：」「HMAC Key：」这类标签、换行、零宽字符）也没关系：系统会先清洗再使用，抠不出来会给一句中文提示。</p><div class="tip custom-block"><p class="custom-block-title">点「测试」不会烧掉 EAB</p><p>授权页的「测试」按钮走的是同一条「注册或复用」链路，注册出来的账户会写回授权，所以不会把一次性的 EAB 用废。</p></div><h2 id="授权类型必须匹配" tabindex="-1">授权类型必须匹配 <a class="header-anchor" href="#授权类型必须匹配" aria-label="Permalink to &quot;授权类型必须匹配&quot;">​</a></h2><p>部署插件会声明自己接受哪些授权类型。选错了会在执行前被拦下来，给一句中文结论，例如：</p><blockquote><p>这个任务需要「群晖 DSM」类型的授权，当前选的是「宝塔面板」</p></blockquote><p>所以「部署到群晖」的下拉里只会出现群晖授权，「部署到宝塔」的只会出现宝塔授权。老数据里如果带着不匹配的授权，字段下方会显示红色提示。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>授权建好了，去 <a href="./issue.html">证书签发</a> 配流水线</li><li>面板 / 云厂商部署细节见 <a href="./deploy.html">部署目标</a></li></ul>',45)])])}const g=d(s,[["render",l]]);export{u as __pageData,g as default};
